<main class="container py-4 py-md-5"><div class="row justify-content-center"><div class="col-12 col-lg-8"><section class="card shadow-sm border-0 p-4"><h1 class="h3 text-center mb-4">Créer un compte</h1><?php if (!empty($success)): ?><div class="alert alert-success"><?= htmlspecialchars($success) ?></div><?php endif; ?><?php if (!empty($error)): ?><div class="alert alert-danger"><?= htmlspecialchars($error) ?></div><?php endif; ?><form action="index.php?page=inscription" method="post" class="row g-3"><div class="col-md-6"><label for="prenom" class="form-label">Prénom</label><input id="prenom" name="prenom" class="form-control" required></div><div class="col-md-6"><label for="nom" class="form-label">Nom</label><input id="nom" name="nom" class="form-control" required></div><div class="col-md-6"><label for="email" class="form-label">E-mail</label><input id="email" type="email" name="email" class="form-control" required></div><div class="col-md-6"><label for="telephone" class="form-label">Téléphone</label><input id="telephone" type="tel" name="telephone" class="form-control" required></div><div class="col-12"><label for="mdp" class="form-label">Mot de passe</label><input id="mdp" type="password" name="mdp" class="form-control" minlength="10" pattern="(?=.*[a-z])(?=.*[A-Z])(?=.*[0-9])(?=.*[^A-Za-z0-9]).{10,}" required><p class="form-text">10 caractères minimum avec majuscule, minuscule, chiffre et caractère spécial.</p></div><div class="col-md-3"><label for="numero_rue" class="form-label">N°</label><input id="numero_rue" name="numero_rue" class="form-control" required></div><div class="col-md-5"><label for="nom_rue" class="form-label">Rue</label><input id="nom_rue" name="nom_rue" class="form-control" required></div><div class="col-md-4"><label for="code_postal" class="form-label">Code postal</label><input id="code_postal" name="code_postal" class="form-control" required></div><div class="col-12"><label for="id_ville" class="form-label">Ville</label><select id="id_ville" name="id_ville" class="form-select" required><option value="">Sélectionnez votre ville</option><?php foreach ($villes as $ville): ?><option value="<?= (int) $ville['id_ville'] ?>"><?= htmlspecialchars($ville['nom_ville']) ?></option><?php endforeach; ?></select></div><div class="col-12 form-check ms-2"><input id="rgpd" class="form-check-input" type="checkbox" name="rgpd" value="1" required><label class="form-check-label" for="rgpd">J'accepte la <a href="?page=confidentialite">politique de confidentialité</a>.</label></div><div class="col-12"><button class="btn btn-primary w-100">Créer mon compte</button></div></form><p class="text-center mt-3 mb-0">Déjà inscrit ? <a href="?page=connexion">Se connecter</a></p></section></div></div></main>
